package com.hikari.engine

import org.json.JSONArray
import org.json.JSONObject

/**
 * One film look, as defined in assets/filters/<id>.json (generated by tools/looks/build_films.py).
 * Colour science lives in the LUT; everything else is a spatial effect the GPU applies at any
 * resolution. Spatial sizes are fractions of the image's short side.
 */
data class FilterSpec(
    val id: String,
    val name: String,
    val zh: String,
    val series: String,
    val note: String,
    val lut: String,
    val lutAmount: Float,
    val exposure: Float,
    val grain: Grain,
    val halation: Halation,
    val bloom: Bloom,
    val diffusion: Diffusion,
    val lens: Lens,
    val defects: Defects,
    /** what this look's colour, grain and glow actually do, generated from its recipe */
    val recipe: List<String> = emptyList(),
    /** the classic film character this original look is inspired by (shown as a hint), or "" */
    val inspired: String = "",
    /** measured traits of the look (tools/looks/traits.py), for the recommender */
    val traits: Map<String, Float> = emptyMap(),
) {
    data class Grain(val amount: Float, val size: Float, val chroma: Float, val rough: Float)
    data class Halation(val amount: Float, val threshold: Float, val radius: Float, val tint: FloatArray)
    data class Bloom(val amount: Float, val threshold: Float, val radius: Float)
    data class Diffusion(val softFocus: Float, val mist: Float, val radius: Float)
    data class Lens(val vignette: Float, val vignetteSoft: Float, val aberration: Float, val edgeSoft: Float)
    data class Defects(
        val dust: Float, val scratches: Float, val leak: Float, val leakColor: FloatArray,
        val uneven: Float, val drift: Float,
    )

    companion object {
        fun parse(text: String): FilterSpec {
            val j = JSONObject(text)
            fun JSONObject.f(k: String) = getDouble(k).toFloat()
            fun JSONArray.v3() = floatArrayOf(getDouble(0).toFloat(), getDouble(1).toFloat(), getDouble(2).toFloat())
            val c = j.getJSONObject("color")
            val g = j.getJSONObject("grain")
            val h = j.getJSONObject("halation")
            val b = j.getJSONObject("bloom")
            val d = j.getJSONObject("diffusion")
            val l = j.getJSONObject("lens")
            val x = j.getJSONObject("defects")
            return FilterSpec(
                id = j.getString("id"), name = j.getString("name"), zh = j.optString("zh", j.getString("name")),
                series = j.getString("series"), note = j.optString("note"), lut = j.getString("lut"),
                lutAmount = c.f("lutAmount"), exposure = c.f("exposure"),
                grain = Grain(g.f("amount"), g.f("size"), g.f("chroma"), g.f("rough")),
                halation = Halation(h.f("amount"), h.f("threshold"), h.f("radius"), h.getJSONArray("tint").v3()),
                bloom = Bloom(b.f("amount"), b.f("threshold"), b.f("radius")),
                diffusion = Diffusion(d.f("softFocus"), d.f("mist"), d.f("radius")),
                lens = Lens(l.f("vignette"), l.f("vignetteSoft"), l.f("aberration"), l.f("edgeSoft")),
                defects = Defects(x.f("dust"), x.f("scratches"), x.f("leak"), x.getJSONArray("leakColor").v3(),
                    x.f("uneven"), x.f("drift")),
                recipe = j.optJSONArray("recipe")?.let { a -> (0 until a.length()).map { a.getString(it) } } ?: emptyList(),
                inspired = j.optString("inspired", ""),
                traits = j.optJSONObject("traits")?.let { t -> t.keys().asSequence().associateWith { t.getDouble(it).toFloat() } } ?: emptyMap(),
            )
        }
    }
}

/**
 * What the user changed on top of a look. null = use the filter's own value. Grain, size,
 * halation, bloom and vignette replace the filter's amounts; exposure, temperature, tint,
 * contrast, saturation and fade are added on top (0 = unchanged).
 */
data class Adjustments(
    val strength: Float = 1f,
    val grain: Float? = null,
    val grainSize: Float? = null,
    val halation: Float? = null,
    val bloom: Float? = null,
    val vignette: Float? = null,
    val fade: Float = 0f,
    val exposure: Float = 0f,
    val temperature: Float = 0f,
    val tint: Float = 0f,
    val contrast: Float = 0f,
    val saturation: Float = 0f,
    // tone regions (-1..1) and capture sharpening (0..1); 0 = unchanged
    val highlights: Float = 0f,
    val shadows: Float = 0f,
    val blacks: Float = 0f,
    val whites: Float = 0f,
    val sharpness: Float = 0f,
    // lens character and film defects: null = the look's own amount, 0 = off
    val aberration: Float? = null,
    val softFocus: Float? = null,
    val mist: Float? = null,
    val edgeSoft: Float? = null,
    val dust: Float? = null,
    val scratches: Float? = null,
    val leak: Float? = null,
    val uneven: Float? = null,
    val drift: Float? = null,
) {
    fun toJson(): String = JSONObject().apply {
        put("strength", strength.toDouble())
        grain?.let { put("grain", it.toDouble()) }
        grainSize?.let { put("grainSize", it.toDouble()) }
        halation?.let { put("halation", it.toDouble()) }
        bloom?.let { put("bloom", it.toDouble()) }
        vignette?.let { put("vignette", it.toDouble()) }
        put("fade", fade.toDouble()); put("exposure", exposure.toDouble())
        put("temperature", temperature.toDouble()); put("tint", tint.toDouble())
        put("contrast", contrast.toDouble()); put("saturation", saturation.toDouble())
        put("highlights", highlights.toDouble()); put("shadows", shadows.toDouble())
        put("blacks", blacks.toDouble()); put("whites", whites.toDouble()); put("sharpness", sharpness.toDouble())
        for ((k, v) in optional()) v?.let { put(k, it.toDouble()) }
    }.toString()

    private fun optional() = listOf(
        "aberration" to aberration, "softFocus" to softFocus, "mist" to mist, "edgeSoft" to edgeSoft,
        "dust" to dust, "scratches" to scratches, "leak" to leak, "uneven" to uneven, "drift" to drift,
    )

    companion object {
        val DEFAULT = Adjustments()

        fun fromJson(text: String?): Adjustments {
            if (text.isNullOrBlank()) return DEFAULT
            val j = JSONObject(text)
            fun opt(k: String): Float? = if (j.has(k) && !j.isNull(k)) j.getDouble(k).toFloat() else null
            return Adjustments(
                strength = opt("strength") ?: 1f, grain = opt("grain"), grainSize = opt("grainSize"),
                halation = opt("halation"), bloom = opt("bloom"), vignette = opt("vignette"),
                fade = opt("fade") ?: 0f, exposure = opt("exposure") ?: 0f,
                temperature = opt("temperature") ?: 0f, tint = opt("tint") ?: 0f,
                contrast = opt("contrast") ?: 0f, saturation = opt("saturation") ?: 0f,
                highlights = opt("highlights") ?: 0f, shadows = opt("shadows") ?: 0f,
                blacks = opt("blacks") ?: 0f, whites = opt("whites") ?: 0f, sharpness = opt("sharpness") ?: 0f,
                aberration = opt("aberration"), softFocus = opt("softFocus"), mist = opt("mist"),
                edgeSoft = opt("edgeSoft"), dust = opt("dust"), scratches = opt("scratches"),
                leak = opt("leak"), uneven = opt("uneven"), drift = opt("drift"),
            )
        }
    }
}
